// The work on the board the factory is connected to, as cards, the same for
// any tracker (cards from a GitHub board, later Jira): listed with the
// factory's stage each is in, shown, moved, commented on, made, and given
// the plan the owner agreed to. The agreed plan lives in the card itself,
// between two marks, so whoever runs the factory (on another computer)
// reads it there.
import { stageLabel, withoutKept } from "@software-factory/core";
import { STAGES } from "../api.js";
import { STAGE_COLUMNS } from "../connect/stages.js";
// What kind of work a card is, kept as a label ("type: bug").
// The branch a card is built on: the same one a prototype of the card is
// pushed to while planning (the plan skill), so the build continues it.
export function branchOf(number) {
    return `factory/issue-${String(number)}`;
}
export const CARD_TYPES = ["bug", "feature", "improvement"];
export const typeLabel = (type) => `type: ${type}`;
// The builder got stuck on the card: it waits in Backlog for the owner,
// apart from the new ideas there.
export const STUCK_LABEL = "factory: stuck";
export function isStuck(labels) {
    return labels.includes(STUCK_LABEL);
}
export function typeOf(labels) {
    return CARD_TYPES.find((type) => labels.includes(typeLabel(type))) ?? null;
}
const START = "<!-- factory:agreed-plan -->";
const END = "<!-- /factory:agreed-plan -->";
// The card's text with the agreed plan in it, in place of an earlier one.
export function withPlan(body, plan) {
    const section = `${START}\n## The agreed plan\n\n${plan.trim()}\n${END}`;
    const at = body.indexOf(START);
    const end = body.indexOf(END);
    if (at >= 0 && end > at)
        return body.slice(0, at) + section + body.slice(end + END.length);
    return body.trim() ? `${body.trimEnd()}\n\n${section}\n` : `${section}\n`;
}
// The agreed plan in a card's text; none when it has none.
export function planOf(body) {
    const at = body.indexOf(START);
    const end = body.indexOf(END);
    if (at < 0 || end <= at)
        return headedPlan(body);
    return body.slice(at + START.length, end).trim();
}
// An earlier factory wrote the plan under its heading only: from there to
// the next heading of the same level.
const PLAN_HEADING = "## The agreed plan";
function headedPlan(body) {
    const at = body.indexOf(`${PLAN_HEADING}\n`);
    if (at < 0)
        return null;
    const from = at + PLAN_HEADING.length;
    const next = body.indexOf("\n## ", from);
    const plan = (next < 0 ? body.slice(from) : body.slice(from, next)).trim();
    return plan || null;
}
// What a card asks for, without its agreed plan.
export function aboutOf(text) {
    const body = withoutKept(text);
    const at = body.indexOf(START);
    const cut = at >= 0 ? at : body.indexOf(`${PLAN_HEADING}\n`);
    return (cut >= 0 ? body.slice(0, cut) : body).trim();
}
// The word the factory uses for a stage when it speaks of it (the board's
// column may be named differently): "ready" for the cards the builder takes.
export function stageWord(stage) {
    return stage === "todo" ? "Ready" : STAGE_COLUMNS[stage].title;
}
// A stage as the owner or an agent names it: its id ("todo"), its title
// ("To do"), or "ready".
export function stageNamed(name) {
    const wanted = name.trim().toLowerCase().replace(/\s+/g, " ");
    if (wanted === "ready")
        return "todo";
    return (STAGES.find((stage) => stage === wanted || STAGE_COLUMNS[stage].title.toLowerCase() === wanted) ?? null);
}
const STUCK_COLOR = "d9534f";
// GitHub's commands that mark a card stuck (making the label when there is
// none yet), or take the mark off; none when it is as asked already.
export function stuckArgs(number, labels, stuck, repo) {
    if (isStuck(labels) === stuck)
        return [];
    const edit = ["issue", "edit", String(number), ...repo];
    if (!stuck)
        return [[...edit, "--remove-label", STUCK_LABEL]];
    return [
        [
            "label",
            "create",
            STUCK_LABEL,
            ...repo,
            "--color",
            STUCK_COLOR,
            "--force",
        ],
        [...edit, "--add-label", STUCK_LABEL],
    ];
}
// GitHub's commands that put a card in a team's stage by a label (made when
// GitHub has none of that name), or take it out of every team's stage.
export function heldArgs(number, labels, held, repo) {
    const wanted = held === null ? null : stageLabel(held);
    const off = labels
        .filter((label) => label.startsWith(stageLabel("")) && label !== wanted)
        .flatMap((label) => ["--remove-label", label]);
    const on = wanted !== null && !labels.includes(wanted);
    const edit = ["issue", "edit", String(number), ...repo];
    return [
        ...(on
            ? [["label", "create", wanted, ...repo, "--color", "8957e5", "--force"]]
            : []),
        ...(on || off.length > 0
            ? [[...edit, ...(on ? ["--add-label", wanted] : []), ...off]]
            : []),
    ];
}
const TYPE_COLORS = {
    bug: "d73a4a",
    feature: "3156d8",
    improvement: "12a594",
};
// GitHub's command that makes the type's label (or updates its colour).
export function labelArgs(type, repo) {
    return [
        "label",
        "create",
        typeLabel(type),
        ...repo,
        "--color",
        TYPE_COLORS[type],
        "--force",
    ];
}
// The label changes that give a card this type (none: no type).
export function typeEdit(labels, type) {
    const off = CARD_TYPES.filter((other) => other !== type && labels.includes(typeLabel(other))).flatMap((other) => ["--remove-label", typeLabel(other)]);
    const on = type && !labels.includes(typeLabel(type))
        ? ["--add-label", typeLabel(type)]
        : [];
    return [...on, ...off];
}
